use vstd::prelude::*;

verus! {

    // Copy a vector of u64's into a new vector, preserving order.
    fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
        requires
            // the input vector is at most length 100
            a.len() <= 100,
        ensures
            // the output has the same length as the input
            b.len() == a.len(),
        ensures
            // each element is preserved
            forall |i: usize| i < a.len() ==> b[i] == a[i],
        ensures
            // hence the output is also at most length 100
            b.len() <= 100,
    {
        // We'll iterate over the input and push each element into b.
        let mut b: Vec<u64> = Vec::new();
        // n is the length of the input, as u64, for arithmetic in the loop
        let n: u64 = a.len() as u64;
        let mut i: u64 = 0;
        while i < n
            invariant
                // loop index never exceeds n
                i <= n,
                // b.len() tracks exactly how many we've copied so far
                (b.len() as u64) == i,
                // for all j < i, the j-th element has been copied correctly
                forall |j: u64| j < i ==> b[j as usize] == a[j as usize],
            decreases
                // ensure termination
                n - i,
        {
            // push the next element
            b.push(a[i as usize]);
            // advance the index
            i = i + 1;
        }
        b
    }
}

